formulas.expression:
OR(
  /* Checkbox */
  $Record.Active__c <> $Record__Prior.Active__c,

  /* Lookup / ID */
  $Record.Active_TVM_Touchpoint_ID__c <> $Record__Prior.Active_TVM_Touchpoint_ID__c,

  /* Date / DateTime */
  $Record.Cancelled_Date__c <> $Record__Prior.Cancelled_Date__c,
  $Record.Website_Go_Live_Date__c <> $Record__Prior.Website_Go_Live_Date__c,
  $Record.Generate_Contract_Profile__c <> $Record__Prior.Generate_Contract_Profile__c,

  /* Text */
  $Record.Client_Team__c <> $Record__Prior.Client_Team__c,

  /* Multi-Select Picklist */
  TEXT($Record.Client_Type_Team_V__c) <> TEXT($Record__Prior.Client_Type_Team_V__c),

  /* Text */
  $Record.Digital_SME__c <> $Record__Prior.Digital_SME__c,

  /* Checkbox */
  $Record.FNDN_Billed_Through_TVM__c <> $Record__Prior.FNDN_Billed_Through_TVM__c,
  $Record.TVM_Billed_Through_FNDN__c <> $Record__Prior.TVM_Billed_Through_FNDN__c,

  /* Digital IDs */
  $Record.Bing_ID__c <> $Record__Prior.Bing_ID__c,
  $Record.Google_CID__c <> $Record__Prior.Google_CID__c,
  $Record.Facebook_ID__c <> $Record__Prior.Facebook_ID__c,

  /* OEM Billing Info - Text */
  $Record.OEM_Dealer_Code__c <> $Record__Prior.OEM_Dealer_Code__c,
  $Record.OEM_Region__c <> $Record__Prior.OEM_Region__c,
  $Record.OEM_Zone__c <> $Record__Prior.OEM_Zone__c,
  $Record.OEM_Serv__c <> $Record__Prior.OEM_Serv__c,
  $Record.OEM_Service_Parts_Code__c <> $Record__Prior.OEM_Service_Parts_Code__c,
  $Record.Google_Payment_ID__c <> $Record__Prior.Google_Payment_ID__c,

/* Basic Fields */
  $Record.OwnerId<> $Record__Prior.OwnerId
)
